def flood_fill_background(grid, bg_color):
    """Return set of cells reachable from edge by background color"""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    queue = []

    # Start BFS from all edge cells that are background
    for c in range(w):
        if grid[0][c] == bg_color:
            visited[0][c] = True
            queue.append((0, c))
    for c in range(w):
        if grid[h-1][c] == bg_color:
            visited[h-1][c] = True
            queue.append((h-1, c))
    for r in range(1, h-1):
        if grid[r][0] == bg_color:
            visited[r][0] = True
            queue.append((r, 0))
        if grid[r][w-1] == bg_color:
            visited[r][w-1] = True
            queue.append((r, w-1))

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                if grid[nr][nc] == bg_color:
                    visited[nr][nc] = True
                    queue.append((nr, nc))
    return visited

