def find_filled_regions(grid, bg, shape, fill):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]

    def bfs_start(r, c, max_size=10):
        """Find background regions up to size max_size"""
        if grid[r][c] != bg:
            return None
        seen = set()
        queue = [(r, c)]
        seen.add((r, c))
        region = []

        while queue:
            cr, cc = queue.pop(0)
            region.append((cr, cc))
            if len(region) > max_size:
                break
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr+dr, cc+dc
                if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen:
                    if grid[nr][nc] == bg:
                        seen.add((nr, nc))
                        queue.append((nr, nc))

        return region

    all_small_regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg and (r, c) not in visited:
                region = bfs_start(r, c, 10)
                if region:
                    all_small_regions.append(region)
                    visited.update(region)

    # Mark which regions should be filled based on output
    filled = {}
    for region in all_small_regions:
        first_cell = region[0]
